.d-life-demo{width:100%;min-height:555px;box-sizing:border-box;padding:20px clamp(5px,4vw,28px);background:#11130e;color:#ececec;font-family:Roboto Mono,JetBrains Mono,monospace}.d-life-demo>header{display:flex;justify-content:space-between;color:#8c8c8c;font:500 8px/1 ui-monospace,monospace;letter-spacing:.14em}.d-life-readout{color:#ececec}.d-life-stage{position:relative;height:430px;margin-top:13px;overflow:hidden;border:1px solid #323232;background:#0a0c08}.d-life-stage canvas{display:block;width:100%;height:100%;touch-action:none;cursor:crosshair}.d-life-stage p{position:absolute;left:11px;bottom:8px;margin:0;padding:4px 6px;background:#0a0c08cc;color:#5f5f5f;font:500 7px/1 ui-monospace,monospace;pointer-events:none}.d-life-demo footer{display:flex;justify-content:center;gap:4px;margin-top:10px;flex-wrap:wrap}.d-life-demo button{min-height:32px;padding:7px 8px;border:1px solid #323232;background:#171b11;color:#8c8c8c;font:500 7px/1 ui-monospace,monospace;text-transform:uppercase;cursor:pointer}.d-life-demo button:hover,.d-life-demo button:focus-visible{background:#ececec;color:#12150c;outline:none}.d-life-status{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
/* Native 320px composition: geometry first, controls second. */
.d-life-demo{position:relative;height:320px;min-height:0;padding:16px;box-sizing:border-box;overflow:hidden;background:#0a0a0b;color:#ececef}
.d-life-demo>header,.d-life-demo>[class$="-head"]{display:none}
.d-life-stage{height:248px;min-height:0;margin:0;box-sizing:border-box;border:0;background:#0a0a0b}
.d-life-demo [class$="-guide"],.d-life-demo [class$="-note"],.d-life-demo [class$="-spec"],.d-life-demo [class$="-hud"],.d-life-stage>p{display:none}
.d-life-demo footer,.d-life-demo>[class$="-foot"]{display:flex;justify-content:center;align-items:center;gap:6px;margin:10px 0 0}
.d-life-demo footer button,.d-life-demo>[class$="-foot"] button{min-height:28px;padding:6px 8px;border:1px solid #333;border-radius:0;background:#161619;color:#b8b8b8;font:500 9px/1.15 'Roboto Mono',monospace;letter-spacing:0}
.d-life-demo footer button:hover,.d-life-demo footer button:focus-visible,.d-life-demo>[class$="-foot"] button:hover,.d-life-demo>[class$="-foot"] button:focus-visible{background:#262626;color:#fa7319;border-color:#fa7319;outline:none}
.d-life-demo>[class$="-foot"]>p{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}

.d-life-demo footer{flex-wrap:nowrap;gap:5px}.d-life-demo footer>button{flex:0 1 auto;min-width:0;white-space:normal;min-height:28px}.d-life-stage{height:240px}

/* Material and typography refinement: calm light, fine edges, purposeful type. */
.d-life-demo{--demo-sans:Manrope,system-ui,sans-serif;--demo-serif:Newsreader,Georgia,serif;font-family:var(--demo-sans)}
.d-life-demo button,.d-life-demo footer button,.d-life-demo>[class$="-foot"] button{font-family:var(--demo-sans);font-size:10px;font-weight:500;line-height:1.2;letter-spacing:.005em;text-transform:none}
.d-life-demo footer button,.d-life-demo>[class$="-foot"] button{border-color:#ffffff16;border-radius:4px;background:linear-gradient(180deg,#202225,#191b1e);color:#b7bdc3}
.d-life-demo footer button:hover,.d-life-demo>[class$="-foot"] button:hover{border-color:#fa73194d;color:#dddfe1;background:#262a2e}
.d-life-demo footer button:focus-visible,.d-life-demo>[class$="-foot"] button:focus-visible{outline:1px solid #fa7319a8;outline-offset:2px}


/* Composition redesign: native sizing, purposeful content and Inter UI. */
.d-life-demo{font-family:Inter,system-ui,sans-serif;background:#111214;font-variant-numeric:tabular-nums}.d-life-demo :where(*){font-family:Inter,system-ui,sans-serif!important;letter-spacing:normal!important;font-variant-numeric:tabular-nums}.d-life-demo :where(code,pre,code *,pre *){font-family:ui-monospace,monospace!important}.d-life-demo footer button,.d-life-demo>[class$="-foot"] button{min-height:29px;padding:6px 10px;border:1px solid #a6bdcc15;border-radius:6px;background:#23303a;color:#a8becd;font:450 11px/1.25 Inter,system-ui,sans-serif;text-transform:none;white-space:nowrap}.d-life-demo footer button:hover,.d-life-demo>[class$="-foot"] button:hover{background:#344550;color:#d5e4ed;border-color:#a6bdcc27}.d-life-demo footer button:focus-visible,.d-life-demo>[class$="-foot"] button:focus-visible{outline:2px solid #9db6c7;outline-offset:2px}.d-life-demo button[class*="-inspect"]{display:none!important}.d-life-demo :where(input){accent-color:#9bb7c8}.d-life-demo :where(h1,h2,h3,h4,b,strong){font-weight:500}
.d-life-stage{border-radius:12px;background:#152723!important}.d-life-stage canvas{opacity:.85}.d-life-clear{display:none!important}.d-life-demo footer button{font-size:11px}.d-life-stage:after{content:'Click to bring a cell to life';position:absolute;left:15px;bottom:12px;pointer-events:none;font-size:10px;color:#668c7c}

